import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { verifyAccessToken } from "@/lib/auth/jwt";

/**
 * Protect company / contractor dashboard — JWT from cookie or header.
 * Matches Waste Pilot sign-in → returnTo=/dashboard flow.
 */
export async function middleware(request: NextRequest) {
  const token =
    request.cookies.get("access_token")?.value ??
    request.headers.get("authorization")?.replace(/^Bearer\s+/i, "");

  if (!token) {
    const signIn = new URL("/auth/jwt/sign-in", request.url);
    signIn.searchParams.set("returnTo", request.nextUrl.pathname);
    return NextResponse.redirect(signIn);
  }

  const session = await verifyAccessToken(token);
  if (!session || !["company", "contractor"].includes(session.role)) {
    return NextResponse.redirect(new URL("/auth/jwt/sign-in", request.url));
  }

  return NextResponse.next();
}
